"use strict";(self.webpackChunkastrana_user_manual=self.webpackChunkastrana_user_manual||[]).push([[519],{1371:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"userManualSidebar":[{"type":"link","label":"User Manual Home","href":"/astrana_doc/","docId":"intro","unlisted":false},{"type":"link","label":"Specifications","href":"/astrana_doc/specifications","docId":"specifications","unlisted":false},{"type":"category","label":"Getting Started","items":[{"type":"link","label":"Unboxing","href":"/astrana_doc/getting-started/unboxing","docId":"getting-started/unboxing","unlisted":false},{"type":"link","label":"Charging","href":"/astrana_doc/getting-started/charging","docId":"getting-started/charging","unlisted":false},{"type":"link","label":"Checking Battery Level","href":"/astrana_doc/getting-started/battery-status","docId":"getting-started/battery-status","unlisted":false},{"type":"link","label":"Pairing","href":"/astrana_doc/getting-started/pairing","docId":"getting-started/pairing","unlisted":false},{"type":"link","label":"First Use","href":"/astrana_doc/getting-started/first-use","docId":"getting-started/first-use","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"User Guide","items":[{"type":"link","label":"Operating Modes","href":"/astrana_doc/user-guide/modes","docId":"user-guide/modes","unlisted":false},{"type":"link","label":"Brightness Control","href":"/astrana_doc/user-guide/brightness-control","docId":"user-guide/brightness-control","unlisted":false},{"type":"link","label":"Color Modes","href":"/astrana_doc/user-guide/color-modes","docId":"user-guide/color-modes","unlisted":false},{"type":"link","label":"Configuration","href":"/astrana_doc/user-guide/configuration","docId":"user-guide/configuration","unlisted":false},{"type":"link","label":"Troubleshooting","href":"/astrana_doc/user-guide/troubleshooting","docId":"user-guide/troubleshooting","unlisted":false},{"type":"link","label":"Frequently Asked Questions","href":"/astrana_doc/user-guide/faq","docId":"user-guide/faq","unlisted":false},{"type":"link","label":"Firmware Update","href":"/astrana_doc/user-guide/fw-update","docId":"user-guide/fw-update","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Maintenance","items":[{"type":"link","label":"Cleaning","href":"/astrana_doc/maintenance/cleaning","docId":"maintenance/cleaning","unlisted":false},{"type":"link","label":"Battery Care","href":"/astrana_doc/maintenance/battery-care","docId":"maintenance/battery-care","unlisted":false},{"type":"link","label":"Safety","href":"/astrana_doc/maintenance/safety","docId":"maintenance/safety","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Support","items":[{"type":"link","label":"Contact Support","href":"/astrana_doc/support/contact","docId":"support/contact","unlisted":false},{"type":"link","label":"Warranty","href":"/astrana_doc/support/warranty","docId":"support/warranty","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"getting-started/battery-status":{"id":"getting-started/battery-status","title":"Checking Battery Level","description":"You don\'t need the web app just to check how much charge is left. With the headlamp powered off (profile 0), press either button once: the status LED pulses a quick color-coded sequence and then returns to off.","sidebar":"userManualSidebar"},"getting-started/charging":{"id":"getting-started/charging","title":"Charging","description":"Astrana runs on a single standard 26650 Li-ion cell, charged in place through the headlamp\'s USB port \u2014 no separate charger required. Charge it fully before first use.","sidebar":"userManualSidebar"},"getting-started/first-use":{"id":"getting-started/first-use","title":"First Use","description":"After charging and pairing, run this first-use checklist to confirm normal operation.","sidebar":"userManualSidebar"},"getting-started/pairing":{"id":"getting-started/pairing","title":"Pairing","description":"Astrana doesn\'t use your phone or computer\'s Bluetooth settings. Instead, the web app connects directly to the headlamp using Web Bluetooth, right from the browser. There is nothing to install and no account to create.","sidebar":"userManualSidebar"},"getting-started/unboxing":{"id":"getting-started/unboxing","title":"Unboxing","description":"This page helps you verify that your Astrana package is complete and ready for setup.","sidebar":"userManualSidebar"},"intro":{"id":"intro","title":"User Manual Home","description":"Everything you need to unbox, configure, and maintain your Astrana headlamp \u2014 from first charge to firmware updates.","sidebar":"userManualSidebar"},"maintenance/battery-care":{"id":"maintenance/battery-care","title":"Battery Care","description":"Astrana uses a single standard 26650 Li-ion cell. Correct handling extends its service life and preserves performance. Astrana also automatically dims Spot/Segment output as the battery nears empty rather than cutting out abruptly \u2014 see Brightness Control.","sidebar":"userManualSidebar"},"maintenance/cleaning":{"id":"maintenance/cleaning","title":"Cleaning","description":"Regular cleaning improves reliability, heat transfer, and connector life.","sidebar":"userManualSidebar"},"maintenance/safety":{"id":"maintenance/safety","title":"Safety","description":"Follow these precautions to reduce risk of injury, overheating, or equipment damage.","sidebar":"userManualSidebar"},"specifications":{"id":"specifications","title":"Specifications","description":"Quick reference for the numbers you\'re likely to look up: what\'s in the box, what it weighs, and the operating limits.","sidebar":"userManualSidebar"},"support/contact":{"id":"support/contact","title":"Contact Support","description":"If you need help, include as much technical context as possible to speed up resolution.","sidebar":"userManualSidebar"},"support/warranty":{"id":"support/warranty","title":"Warranty","description":"Warranty terms can vary by region and distribution channel. Refer to your purchase documentation for legal details.","sidebar":"userManualSidebar"},"user-guide/brightness-control":{"id":"user-guide/brightness-control","title":"Brightness Control","description":"Spot and Segment each have their own brightness, set per-profile (see Operating Modes). Beyond the profiles you configure, Astrana adjusts brightness automatically in three situations described below \u2014 it\'s worth knowing about these so unexpected dimming doesn\'t read as a malfunction.","sidebar":"userManualSidebar"},"user-guide/color-modes":{"id":"user-guide/color-modes","title":"Color Modes","description":"Alongside the white Spot and Segment beams, Astrana has an RGB LED for colored light and a separate UV (ultraviolet) LED. Both are configured per-profile, right alongside brightness (see Operating Modes).","sidebar":"userManualSidebar"},"user-guide/configuration":{"id":"user-guide/configuration","title":"Configuration","description":"All configuration happens in the web app while connected over Bluetooth (see Pairing) \u2014 there\'s no separate companion app or account involved.","sidebar":"userManualSidebar"},"user-guide/faq":{"id":"user-guide/faq","title":"Frequently Asked Questions","description":"Which browser do I need?","sidebar":"userManualSidebar"},"user-guide/fw-update":{"id":"user-guide/fw-update","title":"Firmware Update","description":"Firmware is the software that controls how Astrana behaves. Updates can bring battery-life improvements, new configuration options, and bug fixes. Astrana updates entirely over Bluetooth from the web app \u2014 no cables, no companion app install, and no Wi-Fi network to join.","sidebar":"userManualSidebar"},"user-guide/modes":{"id":"user-guide/modes","title":"Operating Modes","description":"Astrana has two independent light outputs, and up to 10 saved profiles that combine them. Understanding this model makes brightness, color, and button behavior much easier to predict.","sidebar":"userManualSidebar"},"user-guide/troubleshooting":{"id":"user-guide/troubleshooting","title":"Troubleshooting","description":"Use this guide for common problems before contacting support.","sidebar":"userManualSidebar"}}}}')}}]);